168→      selectedOption: itemKey ? { itemKey, label: label ?? itemKey } : null,
169→    };
170→  }, [selectedItemDetailsRef.current]);
171→  const { anchor } = useMenuAnchor({
172→    children,
173→    isOpen,
174→    setIsOpen,
175→    listBoxId,
176→    getReferenceProps,
177→    refs,
178→    onKeyDown: onAnchorKeyDown,
179→    getRenderArgs,
180→  });
181→
182→  // Use external element as the reference, if provided
183→  React.useLayoutEffect(() => {
184→    if (anchorRef?.current) {
185→      refs.setReference(anchorRef.current);
186→    }
187→  }, [anchorRef, refs]);
188→
189→  useMenuImperativeRef({ ref, isOpen, setIsOpen, floatingRef: refs.floating });
190→
191→  const floatingProps = getFloatingProps({
192→    popover: 'manual',
193→    style: floatingStyles,
194→    className: cx(cl['bk-menu-provider__list-box']),
195→  });
196→
197→  const mergedProps = mergeProps(
198→    floatingProps,
199→    propsRest,
200→    {
201→      onKeyDown: mergeCallbacks([propsRest.onKeyDown, onMenuKeyDown]),
202→    },
203→  );
204→
205→  const mergedListBoxRef = mergeRefs<React.ComponentRef<typeof ListBox.ListBox>>(
206→    listBoxRef,
207→    refs.setFloating,
208→    floatingProps.ref as React.Ref<React.ComponentRef<typeof ListBox.ListBox>>,
209→  );
210→
211→  const selectedFromInternalSelected = React.useMemo(() => {
212→    return internalSelected.keys().next().value ?? null; // 'null' for controlled 'ListBox'
213→  }, [internalSelected]);
214→
215→  const handleSelect = React.useCallback((_key: null | ListBox.ItemKey, itemDetails: null | ListBox.ItemDetails) => {
216→    const label = itemDetails?.label ?? null;
217→    const itemKey = itemDetails?.itemKey ?? null;
218→    onSelect?.(itemKey, itemKey === null ? null : { itemKey, label: (label ?? itemKey) });
219→    handleInternalSelect(itemKey ? new Map([[itemKey, { label: label ?? itemKey }]]) : new Map());
220→  }, [onSelect, handleInternalSelect]);
221→
222→  return (
223→    <>
224→      {anchor}
225→      {isMounted && (
226→        <ListBox.ListBox
227→          {...mergedProps}
228→          ref={mergedListBoxRef}
229→          size={menuSize}
230→          label={label}
231→          selected={selectedFromInternalSelected}
232→          defaultSelected={defaultSelected}
233→          onSelect={handleSelect}
234→          onToggle={handleToggle}
235→          data-placement={floatingPlacement}
236→        >
237→          {typeof items === 'function'
238→            ? items({ close: () => { setIsOpen(false); } })
239→            : items}
240→        </ListBox.ListBox>
241→      )}
242→    </>
243→  );
244→}, {
245→    Static: ListBox.Static,
246→    Option: ListBox.Option,
247→    Action: ListBox.Action,
248→    Header: ListBox.Header,
249→    FooterActions: ListBox.FooterActions,
250→  },
251→);
252→
253→

150→    
151→    return (
152→      <DialogContext value={dialogContext}>
153→        <dialog
154→          open
155→          //role="dialog" // Default role. Change this to `role="alertdialog"` for things like confirmation modals.
156→          aria-labelledby={`${dialogId}-title`}
157→          aria-describedby={`${dialogId}-content`}
158→          {...scrollerProps}
159→          {...propsRest}
160→          ref={mergeRefs(dialogRef, propsRest.ref)}
161→          className={cx(
162→            'bk',
163→            { [cl['bk-dialog']]: !unstyled },
164→            { [cl['bk-dialog--loading']]: state === 'loading' },
165→            { [cl['bk-dialog--flat']]: flat },
166→            { [cl['bk-dialog--icon-aside']]: iconAside },
167→            scrollerProps.className,
168→            propsRest.className,
169→          )}
170→          onClose={handleClose}
171→        >
172→          <header className={cx(cl['bk-dialog__header'])}>
173→            <H5 id={`${dialogId}-title`} className={cx(cl['bk-dialog__header__title'])}>{title}</H5>
174→            
175→            <div className={cx(cl['bk-dialog__header__actions'])}>
176→              {showCloseIcon &&
177→                <ActionIcon
178→                  icon="cross"
179→                  autoFocus={autoFocusClose}
180→                  label="Close dialog"
181→                  tooltip={null}
182→                  className={cx(cl['bk-dialog__header-action-close'])}
183→                  onPress={onRequestClose}
184→                />
185→              }
186→            </div>
187→          </header>
188→          
189→          <div className={cl['bk-dialog__content']}>
190→            {iconAside && (
191→              <aside className={cx(cl['bk-dialog__content__icon-aside'])}>
192→                {iconAside}
193→              </aside>
194→            )}
195→            <section
196→              id={`${dialogId}-content`} // Used with `aria-describedby`
197→              role="document" // https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Roles/document_role
198→              // FIXME: make this focusable instead of the <dialog> as per guidelines on MDN?
199→              //tabIndex={0}
200→              className={cx(cl['bk-dialog__content__body'], 'bk-prose')}
201→              inert={state === 'loading'}
202→            >
203→              {children}
204→            </section>
205→          </div>
206→
207→          {state === 'loading' && (
208→            <div className={cl['bk-dialog__loader']}>
209→              <Spinner size="medium"/>
210→            </div>
211→          )}
212→
213→          {(showCancelAction || actions) &&
214→            <footer className={cx(cl['bk-dialog__actions'])}>
215→              {showCancelAction && <CancelAction/>}
216→              {actions}
217→            </footer>
218→          }
219→        </dialog>
220→      </DialogContext>
221→    );
222→  },
223→  {
224→    Action,
225→    ActionIcon,
